"use client";
import {useState} from 'react';
import type {SupabaseClient} from '@supabase/supabase-js';
import {AssistantWorkspaceProvider,AssistantTarget,useAssistantScreen} from '@/components/assistant-workspace';
import {AssistantForm} from '@/components/assistant-form';
const entries:unknown[]=[];
const client={auth:{getSession:async()=>({data:{session:{access_token:'synthetic'}}})},rpc:async(_name:string,args:{p_action:string;p_payload:Record<string,string>})=>{let data:unknown=[];if(args.p_action==='create_conversation')data={id:args.p_payload.id,title:'Teste',context_id:args.p_payload.contextId,context_kind:'general',created_at:new Date().toISOString(),updated_at:new Date().toISOString()};if(args.p_action==='list')data=entries;if(args.p_action==='append'){data={id:entries.length+1,message:args.p_payload.message,reply:args.p_payload.reply,created_at:new Date().toISOString()};entries.push(data);}return {data,error:null};}} as unknown as SupabaseClient;
function Form(){const [title,setTitle]=useState(''),[prefix,setPrefix]=useState(''),[mode,setMode]=useState<'draft'|'record'>('draft');useAssistantScreen({area:'Atividades',filters:{from:'2026-09-09',until:'2026-09-09'}});return <main className="max-w-lg p-4"><AssistantTarget id="root" label="Atividades" priority={0} revision="1" content={null}/><label>Título<input aria-label="Título" value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Prefixo<select aria-label="Prefixo" value={prefix} onChange={e=>setPrefix(e.target.value)}><option value=""/><option>PR-CHT</option></select></label><button onClick={()=>setMode(mode==='draft'?'record':'draft')}>Alternar modo</button><AssistantForm client={client} user="TEST" form={{id:'form-test',label:'Nova atividade',mode,fields:{title:{label:'Título',value:title},prefix:{label:'Prefixo',value:prefix,options:['','PR-CHT']}}}} onApply={values=>{if(values.title!==undefined)setTitle(values.title);if(values.prefix!==undefined)setPrefix(values.prefix);}}/></main>;}
export default function Page(){return <AssistantWorkspaceProvider><Form/></AssistantWorkspaceProvider>;}
